import{_ as s,o,c as t,a0 as r}from"./chunks/framework.DVUHX04-.js";const u=JSON.parse('{"title":"Usage reports are derived from session files, not a stored index","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0008-usage-report-derived-from-session-scan.md","filePath":"adr/0008-usage-report-derived-from-session-scan.md","lastUpdated":1789465415000}'),a={name:"adr/0008-usage-report-derived-from-session-scan.md"};function n(i,e,d,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="usage-reports-are-derived-from-session-files-not-a-stored-index" tabindex="-1">Usage reports are derived from session files, not a stored index <a class="header-anchor" href="#usage-reports-are-derived-from-session-files-not-a-stored-index" aria-label="Permalink to &quot;Usage reports are derived from session files, not a stored index&quot;">​</a></h1><p>pi already records complete usage on every assistant message, tool result that did nested LLM work, and compaction entry in the session JSONL files. Every Usage report is therefore derived on demand by a Usage scan over those files, and the extension keeps no live log or stored aggregate.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Live append log written by the extension while sessions run.</strong> Faster, but a second source of truth that misses events pi recorded without the extension (or on another machine) and drifts from the session files it would duplicate.</li><li><strong>Stored index rebuilt incrementally.</strong> The same duplication problem, plus a cache to invalidate.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A report is always complete and consistent with what pi shows per session, even for sessions that predate the extension.</li><li>Every report pays a full scan. At about 900 MB of session data the scan takes roughly 1.5 seconds, which is the accepted price for a single source of truth. If that ever stops being cheap, the scan is the thing to optimize, not to replace.</li></ul>',6)])])}const f=s(a,[["render",n]]);export{u as __pageData,f as default};
